#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;vector<long long>st;st.push_back(0);
for(char c:s){
if(c=='(')st.push_back(0);
else{long long v=st.back();st.pop_back();
st.back()+=max(2*v,1LL);}}
printf("%lld\n",st.back());return 0;}

